/* D12 design tokens (rearch/06; colour and type per console-radar-theme). Dark is the source of truth.
 * Navy grounds + enterprise blue accent (agent-builder parity). Components NEVER hardcode colors — tokens only. */
:root,
html[data-theme="dark"] {
  --bg-primary: #0a0f1a;
  --bg-secondary: #101828;
  --bg-tertiary: #16233a;
  --bg-elevated: #101828;

  --text-primary: #e6edf7;
  --text-secondary: #8494ac;
  --text-tertiary: #5a6a85;
  --text-disabled: #475569;
  --text-inverse: #0a0f1a;

  --border-primary: #1e2a40;
  --border-secondary: #2a3a58;
  --border-focus: #2563eb;

  /* Dark enough that white --text-on-accent clears WCAG AA 4.5:1 on small button labels. */
  --accent-primary: #2563eb;
  --accent-primary-hover: #1d4ed8;
  --accent-primary-light: #1e3a8a;
  --text-on-accent: #ffffff;
  --accent-success: #34d399;
  --accent-warning: #ffb547;
  --accent-error: #f87171;
  --accent-teal: #2dd4bf;
  --accent-info: #60a5fa;
  --accent-fuchsia: #e879f9;
  --accent-sky: #38bdf8;
  --accent-violet: #a78bfa;

  --surface-card: #101828;
  --surface-hover: #16233a;
  --surface-active: #1e2a40;
  --surface-selected: #1e3a8a;
  /* legacy globals.css (controller desk D4c): the modal backdrop, and the field ground the desk's
     text inputs sit on (legacy writes it as `bg-[var(--bg-primary)]`). */
  --bg-overlay: rgba(0, 0, 0, 0.6);
  --surface-input: #0a0f1a;

  --grid-line: rgba(59, 130, 246, 0.08);
  --radius-md: 0.375rem;
  --radius-lg: 0.5rem;
  --radius-xl: 0.75rem;

  --font-sans: "IBM Plex Sans", ui-sans-serif, system-ui, sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, Menlo, monospace;
  --shadow-sm: 0 1px 2px 0 #0000004d;
  --shadow-md: 0 4px 6px -1px #0006, 0 2px 4px -1px #0000004d;
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.5), 0 4px 6px -2px rgba(0, 0, 0, 0.3); /* legacy globals.css (controller desk D2) */

